#!/bin/sh
# Run only in an isolated disposable runtime container with fixtures generated by
# TestGenerateRuntimeFixtures mounted at /security-fixtures (same absolute paths).
set -eu
work=$(mktemp -d)
nginx_pid=
cleanup() { [ -z "$nginx_pid" ] || kill "$nginx_pid" 2>/dev/null || true; rm -rf "$work"; }
trap cleanup EXIT HUP INT TERM
chmod 755 "$work"
test -s /security-fixtures/sites/a.conf
test -s /security-fixtures/sites/b.conf
cat > /usr/share/modsecurity-crs/rules/REQUEST-999-SMOKE.conf <<'RULES'
SecRule ARGS:policytest "@streq scoped" "id:999998,phase:2,t:none,deny,status:403,log,msg:scoped-test"
SecRule ARGS:query "@streq scoped" "id:999997,phase:2,t:none,deny,status:403,log,msg:target-test"
RULES
mkdir -p /etc/crowdsec/bouncers
cat > /etc/crowdsec/bouncers/crowdsec-nginx-bouncer.conf <<'BOUNCER'
ENABLED=true
API_URL=http://127.0.0.1:18081
API_KEY=smoke-only-not-a-secret
MODE=live
CACHE_EXPIRATION=1
BOUNCING_ON_TYPE=all
FALLBACK_REMEDIATION=ban
RET_CODE=403
BAN_TEMPLATE_PATH=/var/lib/crowdsec/lua/templates/ban.html
BOUNCER
cat > "$work/nginx.conf" <<CONFIG
include /etc/nginx/modules-enabled/*.conf;
pid $work/nginx.pid;
error_log $work/error.log notice;
events {}
http {
 include /usr/local/share/nginx-ui-security/crowdsec-init.conf;
 server { listen 127.0.0.1:18081;
  location /v1/decisions { content_by_lua_block {
   local file=io.open('$work/ban','r');
   if file then file:close(); ngx.say('[{"type":"ban","origin":"cscli","value":"127.0.0.1","scope":"Ip"}]') else ngx.print('null') end
  } }
 }
 server { listen 127.0.0.1:8080; location / { content_by_lua_block { ngx.say('fixture upstream') } } }
 include /security-fixtures/sites/*.conf;
}
CONFIG
nginx -t -c "$work/nginx.conf"
nginx -c "$work/nginx.conf" -g 'daemon off;' &
nginx_pid=$!
code() { curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:$1/$2"; }
for attempt in 1 2 3 4 5; do
 if curl -fsS http://127.0.0.1:8081/ >/dev/null 2>&1; then break; fi
 sleep 1
done
test "$(code 8081 '')" = 200
test "$(code 8082 '')" = 200
test "$(code 8081 '?policytest=scoped')" = 403
test "$(code 8082 '?policytest=scoped')" = 200
test "$(code 8081 'search?query=scoped')" = 403
test "$(code 8082 'search?query=scoped')" = 200
test "$(code 8082 'other?query=scoped')" = 403
test "$(code 8082 'private?token=harmless')" = 403
test "$(code 8082 'private-more')" = 200
test "$(code 8081 'private?token=harmless')" = 200
attack='?q=%3Cscript%3Ealert(1)%3C/script%3E'
test "$(code 8081 "$attack")" = 403
test "$(code 8082 "$attack")" = 403
touch "$work/ban"
sleep 2
test "$(code 8081 '')" = 403
test "$(code 8082 '')" = 200
rm "$work/ban"
sleep 2
test "$(code 8081 '')" = 200
printf '%s\n' 'PASS: actual Service.ApplyWAF/ApplySite-generated policy and snippets validate in Nginx; isolated scoped exceptions/path blocks/CRS and CrowdSec enforcement all pass'
